  subject = '📘 Evening study check — did you hit 30 minutes?';
  msg = 'Free day evening check: did you study for at least 30 minutes today? If not, there is still time. Open your laptop, even 20 minutes counts.';
} else {
  subject = '📘 Light study reminder — just 20 minutes';
  msg = 'Work day evening. You had a 12H shift — just review your notes for 20 minutes. No new topics. Then rest, you earned it.';
